import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # 1. Distinct by seq (at-least-once delivery -> apply once)
    events = cdc_events.drop_duplicates(subset="seq", keep="first")

    # Build lookup of original target_state rows keyed by order_id
    target_map = {}
    for _, row in target_state.iterrows():
        target_map[row["order_id"]] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
        }

    new_state_rows = []
    tombstone_rows = []
    processed_orders = set()

    if not events.empty:
        groups = events.groupby("order_id")
    else:
        groups = []

    for order_id, grp in (groups if not events.empty else []):
        processed_orders.add(order_id)
        grp_sorted = grp.sort_values("seq")

        orig = target_map.get(order_id)

        # 2. Replay guard based on ORIGINAL target_state row only
        if orig is not None:
            guard_seq = orig["last_seq"]
            grp_sorted = grp_sorted[grp_sorted["seq"] > guard_seq]

        # current working state for this order
        if orig is not None:
            exists = True
            status = orig["status"]
            amount = orig["amount"]
            last_seq = orig["last_seq"]
        else:
            exists = False
            status = None
            amount = None
            last_seq = None

        had_row_ever = exists
        last_eff_op = None
        last_eff_seq = None

        # 3. Apply remaining events in seq order
        for _, ev in grp_sorted.iterrows():
            op = ev["op"]
            seq = ev["seq"]

            if op in ("I", "U"):
                if exists:
                    status = ev["status"]
                    if op == "U" and pd.isna(ev["amount"]):
                        # keep existing amount unchanged
                        pass
                    else:
                        amount = ev["amount"]
                else:
                    status = ev["status"]
                    amount = ev["amount"]
                    exists = True
                last_seq = seq
                had_row_ever = True
                last_eff_op = op
                last_eff_seq = seq
            elif op == "D":
                if exists:
                    exists = False
                    last_seq = seq
                    last_eff_op = "D"
                    last_eff_seq = seq
                # D on a missing order: no-op, no effect at all

        if exists:
            new_state_rows.append(
                {
                    "order_id": order_id,
                    "status": status,
                    "amount": amount,
                    "last_seq": last_seq,
                }
            )

        if had_row_ever and last_eff_op == "D":
            tombstone_rows.append(
                {"order_id": order_id, "deleted_seq": last_eff_seq}
            )

    # 4. Carry forward orders untouched by any applied event
    for order_id, info in target_map.items():
        if order_id not in processed_orders:
            new_state_rows.append(
                {
                    "order_id": order_id,
                    "status": info["status"],
                    "amount": info["amount"],
                    "last_seq": info["last_seq"],
                }
            )

    new_state_df = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    tombstones_df = pd.DataFrame(
        tombstone_rows, columns=["order_id", "deleted_seq"]
    )

    if not new_state_df.empty:
        new_state_df["order_id"] = new_state_df["order_id"].astype("int64")
        new_state_df["last_seq"] = new_state_df["last_seq"].astype("int64")
        new_state_df["amount"] = new_state_df["amount"].astype("float64")
        new_state_df["status"] = new_state_df["status"].astype(object)
    else:
        new_state_df = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype=object),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    if not tombstones_df.empty:
        tombstones_df["order_id"] = tombstones_df["order_id"].astype("int64")
        tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype("int64")
    else:
        tombstones_df = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state_df, "tombstones": tombstones_df}
